<script setup lang="ts">
import type{DataRow,PageConfig}from'~/types/platform';const props=defineProps<{page:PageConfig;routePath:string}>();const{request}=useApi();const{showToast}=useToast();const model=reactive<DataRow>({});const id=ref('');onMounted(async()=>{const r=await request<{data:DataRow[]}>(props.routePath,{query:{limit:1}});if(r.data[0]){Object.assign(model,r.data[0]);id.value=String(r.data[0].id)}});const save=async()=>{if(id.value)await request(`${props.routePath}/${encodeURIComponent(id.value)}`,{method:'PUT',body:model});showToast('Meeting saved.')};const agenda=['Operational performance','Project delivery','Sales pipeline','Finance and cash flow','Action items']
</script>
<template><PageActions primary-label="Save Meeting" :hide-import="true" :hide-filter="true" @create="save" @export="showToast('Meeting export prepared.')" @refresh="showToast('Meeting refreshed.')" @more="showToast('More actions.')"/><section class="meeting-layout"><article class="platform-card meeting-form-card"><div class="platform-card-head"><h2>Meeting Information</h2></div><div class="meeting-form-grid" style="padding-top:12px"><label v-for="field in [['meetingNo','Meeting No'],['meetingType','Meeting Type'],['date','Date'],['time','Time'],['location','Location'],['chairman','Chairman'],['participants','Participants'],['status','Status']]" :key="field[0]" class="platform-field"><span>{{field[1]}}</span><input v-model="model[field[0]]"></label><label class="platform-field" style="grid-column:1/-1"><span>Agenda</span><textarea v-model="model.agenda" rows="5"/></label></div></article><aside class="platform-card meeting-side"><div class="platform-card-head"><h2>Agenda Preview</h2></div><div v-for="(item,index) in agenda" :key="item" class="agenda-item"><b>{{index+1}}. {{item}}</b><small>{{[20,25,20,25,10][index]}} min · Presenter {{['Budi Santoso','Sari Dewi','Andi Wijaya','Rina Marlina'][index%4]}}</small></div></aside></section></template>
